<?php
namespace Tests\Feature;use App\Models\{Institution,Survey,User};use Database\Seeders\RolesAndPermissionsSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\Storage;use Tests\TestCase;
class MeasurementCollectionTest extends TestCase{use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed(RolesAndPermissionsSeeder::class);}private function context():array{$u=User::factory()->create();$u->assignRole('Network Admin');$i=Institution::create(['name'=>'Test','slug'=>'test']);$c=$i->campuses()->create(['name'=>'Main','code'=>'M']);$b=$c->buildings()->create(['name'=>'Library','code'=>'L']);$f=$b->floors()->create(['name'=>'Ground','code'=>'G','level_number'=>0]);$fp=$f->floorPlans()->create(['uploaded_by'=>$u->id,'original_name'=>'p.png','file_path'=>'p','mime_type'=>'image/png','file_size'=>1,'original_width'=>1000,'original_height'=>800,'version'=>1,'is_active'=>true]);$s=Survey::create(['floor_id'=>$f->id,'floor_plan_id'=>$fp->id,'created_by'=>$u->id,'name'=>'Baseline']);$p=$s->points()->create(['floor_plan_id'=>$fp->id,'captured_by'=>$u->id,'x_normalized'=>.2,'y_normalized'=>.3,'source_type'=>'measured','collection_method'=>'manual','validation_status'=>'pending','captured_at'=>now()]);return[$u,$s,$p];}public function test_admin_can_store_real_measurement():void{[$u,$s,$p]=$this->context();$this->actingAs($u)->postJson("/api/measurement-points/{$p->id}/measurements",['rssi_dbm'=>-58,'download_mbps'=>42.5,'latency_ms'=>25,'packet_loss_percent'=>.5,'source_type'=>'measured','collection_method'=>'manual'])->assertCreated()->assertJson(['rssi_dbm'=>-58,'is_simulated'=>false]);$this->assertDatabaseHas('measurement_points',['id'=>$p->id,'validation_status'=>'valid']);}public function test_simulated_measurement_is_labelled():void{[$u,$s,$p]=$this->context();$this->actingAs($u)->postJson("/api/measurement-points/{$p->id}/measurements",['rssi_dbm'=>-70,'source_type'=>'simulated','collection_method'=>'prototype'])->assertCreated()->assertJson(['is_simulated'=>true]);}public function test_csv_import_accepts_valid_row():void{Storage::fake('local');[$u,$s,$p]=$this->context();$csv="x_normalized,y_normalized,rssi_dbm,captured_at\n0.4,0.5,-60,2026-11-04T09:30:00+01:00\n";$file=UploadedFile::fake()->createWithContent('survey.csv',$csv);$this->actingAs($u)->postJson("/api/surveys/{$s->id}/measurement-imports",['file'=>$file])->assertCreated()->assertJson(['status'=>'completed','accepted_rows'=>1,'rejected_rows'=>0]);}}
